package dashboard

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"net/http"
	"os"
	"path/filepath"
)

// blueprintsFile is where the dashboard records which blueprint a system
// follows. The assignment is dashboard state, not part of the scaffold
// record: the CLI renders blueprints nowhere, so writing it into
// .intropy/scaffold.json would bypass the render path that owns that file.
const blueprintsFile = "dashboard-blueprints.json"

// getBlueprints is GET /api/blueprints: the blueprint each system follows,
// keyed by root-relative system path. Unknown systems follow the general
// blueprint; the file only ever carries explicit choices.
func (s *apiServer) getBlueprints(w http.ResponseWriter, _ *http.Request) {
	m, err := s.readBlueprints()
	if err != nil {
		writeError(w, http.StatusInternalServerError, err.Error())
		return
	}
	writeJSON(w, http.StatusOK, m)
}

// setBlueprint is PUT /api/blueprints/{path...}: record the blueprint one
// system follows. The value is stored verbatim — the catalog lives in the
// SPA, so the server cannot validate against it; an unknown value simply
// renders as the general skeleton until the SPA catches up.
func (s *apiServer) setBlueprint(w http.ResponseWriter, r *http.Request) {
	rel, err := cleanRelPath(r.PathValue("path"))
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	var body struct {
		Blueprint string `json:"blueprint"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil || body.Blueprint == "" {
		writeError(w, http.StatusBadRequest, "body must be {\"blueprint\": \"<name>\"}")
		return
	}
	m, err := s.readBlueprints()
	if err != nil {
		writeError(w, http.StatusInternalServerError, err.Error())
		return
	}
	m[rel] = body.Blueprint
	if err := s.writeBlueprints(m); err != nil {
		writeError(w, http.StatusInternalServerError, err.Error())
		return
	}
	writeJSON(w, http.StatusOK, m)
}

// readBlueprints loads the assignment file; a missing file is an empty map,
// not an error — a workspace with no choices yet is the common case.
func (s *apiServer) readBlueprints() (map[string]string, error) {
	data, err := os.ReadFile(filepath.Join(s.root, ".intropy", blueprintsFile))
	if errors.Is(err, fs.ErrNotExist) {
		return map[string]string{}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("read blueprint assignments: %w", err)
	}
	m := map[string]string{}
	if err := json.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("read blueprint assignments: %w", err)
	}
	return m, nil
}

func (s *apiServer) writeBlueprints(m map[string]string) error {
	dir := filepath.Join(s.root, ".intropy")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("write blueprint assignments: %w", err)
	}
	data, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return fmt.Errorf("write blueprint assignments: %w", err)
	}
	data = append(data, '\n')
	return os.WriteFile(filepath.Join(dir, blueprintsFile), data, 0o644)
}

