import type { SlotKind } from './components/CreateDrawer'

// The blueprint catalog: a named composition of slot placeholders and topic
// placeholders that shapes a system's canvas while slots remain unfilled.
// A blueprint is a starting layout plus the facts its slots share — it
// never restricts what a slot can scaffold, and the canvas degrades to
// rendering the declared topology as blocks fill in.
//
// Column semantics mirror the flow layout's archetype positions: 0 is the
// in-boundary (extractors), outCol the out-boundary (loaders), and the
// middle carries processing (transactional blocks, topics). The flow view
// stretches `out` to its effective out column, so a blueprint never
// hardcodes a column count.

export type BlueprintColumn = 'in' | 'mid' | 'out'

export interface BlueprintSlot {
  kind: SlotKind
  col: BlueprintColumn
}

export interface BlueprintTopic {
  /** Placeholder label until the fact names it, e.g. "topic". */
  label: string
  col: BlueprintColumn
  /** Slot indexes publishing into this topic. */
  publishers: number[]
  /** Slot indexes subscribed to this topic. */
  subscribers: number[]
  /** Fact whose value names the topic once entered. */
  fact?: string
}

export interface BlueprintFact {
  key: string
  label: string
  /** Template parameter names this fact pre-fills in a slot's create form. */
  params: string[]
}

export interface Blueprint {
  id: string
  name: string
  blurb: string
  slots: BlueprintSlot[]
  topics: BlueprintTopic[]
  /** Facts asked once on the canvas and pre-filled into every slot form. */
  facts: BlueprintFact[]
}

const general: Blueprint = {
  id: 'general',
  name: 'General',
  blurb: 'Build the system freely — one slot per block kind, no shared facts.',
  slots: [
    { kind: 'extractor', col: 'in' },
    { kind: 'transactional', col: 'mid' },
    { kind: 'loader', col: 'out' },
  ],
  topics: [],
  facts: [],
}

const distribution: Blueprint = {
  id: 'distribution',
  name: 'Distribution',
  blurb: 'One extractor publishes a contract on a topic; loaders subscribe and deliver.',
  slots: [
    { kind: 'extractor', col: 'in' },
    { kind: 'loader', col: 'out' },
  ],
  topics: [
    {
      label: 'topic',
      col: 'mid',
      publishers: [0],
      subscribers: [1],
      fact: 'topic',
    },
  ],
  facts: [
    { key: 'topic', label: 'topic', params: ['topic'] },
    { key: 'contract', label: 'contract', params: ['contract'] },
  ],
}

const transactional: Blueprint = {
  id: 'transactional',
  name: 'Transactional',
  blurb: 'A single transactional integration — request in, response out.',
  slots: [{ kind: 'transactional', col: 'mid' }],
  topics: [],
  facts: [],
}

export const BLUEPRINTS: Blueprint[] = [general, distribution, transactional]

export function blueprintById(id: string | undefined): Blueprint {
  return BLUEPRINTS.find((b) => b.id === id) ?? general
}

/** The canvas column a blueprint column lands on, given the layout's
 *  archetype column indexes. */
export function columnFor(
  col: BlueprintColumn,
  cols: { extractor: number; transactional: number; loader: number },
): number {
