edits.newText:
// Placeholder slots. The selected blueprint contributes its composition
// as long as none of its slots is filled: those slots sit in the flow
// itself, wired through the blueprint's topic placeholders, so the canvas
// reads as the composition to build. Once any blueprint slot is filled
// the guide dissolves and the plain rail takes over — one slot per kind
// column, pinned below the flow — because the graph can no longer tell
// which real node replaced which slot. Either way, clicking a slot opens
// the create drawer pre-filtered to that block kind; slots are
// affordances, never part of the graph.
const countKind = (kind: SlotKind): number => {
  const want = KIND_DATA_FLOW_FALLBACK[kind]
  const matches = (flow: DataFlow | undefined, k: string) =>
    (flow ?? dataFlowFor(k)) === want
  return (
    comps.filter((c) => matches(dataFlowFor(c.kind), c.kind)).length +
    ghosts.filter((g) =>
      matches(g.dataFlow, g.blockKind || g.template),
    ).length
  )
}
