  guideActive
    ? blueprint.slots.map((s, i) => ({
        kind: s.kind,
        col: columnFor(s.col, {
          extractor: extractorCol,
          transactional: transactionalCol,
          loader: loaderCol,
        }),
        slot: i,
      }))
    : [
        { kind: 'extractor', col: extractorCol },
        { kind: 'transactional', col: transactionalCol },
        { kind: 'loader', col: loaderCol },
