// Slot placement. In guide mode the blueprint's slots and topic
// placeholders stack into their columns like real nodes and wire to each
// other; on the rail they share one baseline below the deepest node so
// they align across columns instead of drifting with each column's
// stack. An empty system has no node bottom — the rail is the content
// top.
const nodeBottom = Math.max(
  0,
  ...colRows.map((rows, col) =>
    rows === 0
      ? 0
      : contentTop +
        ((maxRows - rows) * (NODE_H + ROW_GAP)) / 2 +
        (rows - 1) * (NODE_H + ROW_GAP) +
        // Guide slots/topics already stacked into the column; the rail
        // sits below them without double-counting their height.
        (guideActive && slotDefs.some((s) => s.col === col)
          ? rows * (NODE_H + ROW_GAP)
          : rows * (NODE_H + ROW_GAP)) -
        (guideActive ? 0 : 0) +
        NODE_H,
  ),
)
const railY = nodeBottom === 0 ? contentTop : nodeBottom + ROW_GAP

if (guideActive) {
  const slotNodeId = (i: number) => `slot:${i}`
  const slotPos: Array<{ x: number; y: number }> = []
  for (const s of slotDefs) {
    const pos = place(s.col)
    slotPos[s.slot ?? 0] = { x: pos.x, y: pos.y }
    nodes.push({
      id: slotNodeId(s.slot ?? 0),
      type: 'slot',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      style: { width: NODE_W, height: NODE_H },
      draggable: false,
      selectable: false,
      data: { kind: s.kind, slot: s.slot } satisfies SlotNodeData,
    })
  }
  for (let ti = 0; ti < blueprint.topics.length; ti++) {
    const t = blueprint.topics[ti]
    const col = columnFor(t.col, {
      extractor: extractorCol,
      transactional: transactionalCol,
      loader: loaderCol,
    })
    const pos = place(col)
    const factVal = t.fact ? factValues[t.fact] : undefined
    nodes.push({
      id: `bptopic:${ti}`,
      type: 'topic',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x + (NODE_W - INFRA_W) / 2, y: pos.y },
      style: { width: INFRA_W, height: INFRA_H },
      draggable: false,
      data: { name: factVal || t.label } satisfies TopicNodeData,
    })
    // The composition's intended wiring, drawn as the same ext-class
    // edges real wiring uses — dashed via the guide's slot endpoints.
    for (const p of t.publishers) {
      edges.push({
        id: `e:bp:${ti}:pub:${p}`,
        source: slotNodeId(p),
        sourceHandle: 'ext',
        target: `bptopic:${ti}`,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-guide',
      })
    }
    for (const sub of t.subscribers) {
      edges.push({
        id: `e:bp:${ti}:sub:${sub}`,
        source: `bptopic:${ti}`,
        sourceHandle: 'out',
        target: slotNodeId(sub),
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-guide',
      })
    }
  }
} else {
  for (const s of slotDefs) {
    nodes.push({
      id: `slot:${s.kind}`,
      type: 'slot',
      parentId: groupId,
      extent: 'parent',
      position: { x: colX(s.col), y: railY },
      style: { width: NODE_W, height: NODE_H },
      draggable: false,
      selectable: false,
      data: { kind: s.kind } satisfies SlotNodeData,
    })
  }
}

const groupHeight =
  (guideActive
    ? Math.max(
        0,
        ...nodes
          .filter((n) => n.parentId === groupId)
          .map((n) => n.position.y + (n.style?.height as number | undefined ?? NODE_H)),
      ) + GROUP_PAD
    : railY + NODE_H + GROUP_PAD)

