// prefillFor maps the blueprint's shared facts onto the template parameter
// names one slot's create form understands. Only facts the user has entered
// propagate, and only through params the blueprint declares — the form
// treats them as seeds, so a template without the parameter ignores them.
function prefillFor(
  blueprint: Blueprint,
  slot: number | undefined,
  factValues: Record<string, string>,
): Record<string, unknown> | undefined {
  if (slot === undefined) return undefined
  const slotKind = blueprint.slots[slot]?.kind
  if (!slotKind) return undefined
  const out: Record<string, unknown> = {}
  for (const f of blueprint.facts) {
    const v = factValues[f.key]
    if (!v) continue
    for (const p of f.params) out[p] = v
  }
  return Object.keys(out).length > 0 ? out : undefined
}

