 * never reads as a real connection. */
.flow-canvas .rf-edge-guide .react-flow__edge-path {
  stroke: var(--text-muted);
  stroke-width: 1.5;
  stroke-dasharray: 2 5;
  opacity: 0.55;
}

.flow-canvas .rf-edge-guide .react-flow__arrowhead {
  fill: var(--text-muted);
  opacity: 0.55;
}

.flow-fact {
  width: 130px;
  padding: 6px 10px;
  font: inherit;
  font-size: 13px;
  color: var(--text);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.flow-fact::placeholder {
  color: var(--text-muted);
}

